questionvariables.text:
/* Sport choice */
sport_number:rand(4)+1;
sport_list:["rugby","football","cricket","basketball"];
sport_choice:sport_list[sport_number];

/* Info for data generation */
dat_min:if sport_number = 1 then 90 elseif sport_number=2 then 60 elseif sport_number=3 then 65 else 90;
dat_max:dat_min+7*(if sport_number = 1 then rand(3)+6 elseif sport_number=3 then rand(3)+2 elseif sport_number=4 then rand(3)+3 else rand(3)+5);
n:2*rand(12)+19;

/* dat4: gamma left skewed */
dat4: makelist(float(quantile_gamma(rand(1.0),3,1)),i,1,n);
dat4: ((dat4-lmin(dat4))/(lmax(dat4)-lmin(dat4)))*(dat_max-dat_min)+dat_min;
dat4: sort(dat4);
dat4: round(dat4);
data:dat4;

/* Defining the Intervals */
basic_width:(dat_max-dat_min)/7;
min1:dat_min;
max1:dat_min+basic_width;
min2:dat_min+basic_width;
max2:dat_min+2*basic_width;
min3:dat_min+2*basic_width;
max3:dat_min+4*basic_width;
min4:dat_min+4*basic_width;
max4:dat_min+7*basic_width;

/* Performing counts */
count_1:0;
count_2:0;
count_3:0;
count_4:0;
for i:1 thru length(data) do (if data[i]<max1 then count_1:count_1+1 elseif data[i]<max2 then count_2:count_2+1 elseif data[i]<max3 then count_3:count_3+1 else count_4:count_4+1);

/* checking that median is not in a border */
for i:1 while (ceiling(n/2)=count_1 or ceiling(n/2)=count_1-1 or ceiling(n/2)=count_1+1 or ceiling(n/2)=count_1+count_2 or ceiling(n/2)=count_1+count_2-1 or ceiling(n/2)=count_1+count_2+1 or ceiling(n/2)=count_1+count_2+count_3 or ceiling(n/2)=count_1+count_2+count_3-1 or ceiling(n/2)=count_1+count_2+count_3+1) do (dat4: makelist(float(quantile_gamma(rand(1.0),3,1)),i,1,n),dat4: ((dat4-lmin(dat4))/(lmax(dat4)-lmin(dat4)))*(dat_max-dat_min)+dat_min,dat4: sort(dat4),dat4: round(dat4),data:dat4,basic_width:(dat_max-dat_min)/7,min1:dat_min,max1:dat_min+basic_width,min2:dat_min+basic_width,max2:dat_min+2*basic_width,min3:dat_min+2*basic_width,max3:dat_min+4*basic_width,min4:dat_min+4*basic_width,max4:dat_min+7*basic_width,count_1:0,count_2:0,count_3:0,count_4:0,for i:1 thru length(data) do (if data[i]<max1 then count_1:count_1+1 elseif data[i]<max2 then count_2:count_2+1 elseif data[i]<max3 then count_3:count_3+1 else count_4:count_4+1));



/* Cumulative Frequencies */
cum_freq_1:count_1;
cum_freq_2:count_1+count_2;
cum_freq_3:count_1+count_2+count_3;
cum_freq_4:count_1+count_2+count_3+count_4;

/* Midpoints */
midpoint_1:(min1+max1)/2;
midpoint_2:(min2+max2)/2;
midpoint_3:(min3+max3)/2;
midpoint_4:(min4+max4)/2;

/* Estimated subtotals */
estimated_subtotal_1:count_1*midpoint_1;
estimated_subtotal_2:count_2*midpoint_2;
estimated_subtotal_3:count_3*midpoint_3;
estimated_subtotal_4:count_4*midpoint_4;

/* totals */
total_freq:n;
total_weight:estimated_subtotal_1+estimated_subtotal_2+estimated_subtotal_3+estimated_subtotal_4;

/* Calculate estimate of mean and actual mean */
estimate_mean:total_weight/n;
actual_mean:mean(data);

/* Interval containing the median */
median_data:median(data);
class_interval_median:if median_data<max1 then 1 elseif median_data<max2 then 2 elseif median_data<max3 then 3 else 4;
ta:[[1, if class_interval_median=1 then true else false, "First Class Interval"],[2, if class_interval_median=2 then true else false, "Second Class Interval"],[3, if class_interval_median=3 then true else false, "Third Class Interval"], [4, if class_interval_median=4 then true else false, "Fourth Class Interval"]]

