/* This only tests the cumulative frequencies */
cum_freq_sans_list:[ans1,ans2,ans3,ans4];
cum_freq_tans_list:[cum_freq_1,cum_freq_2,cum_freq_3,cum_freq_4]

/* This only tests the estimated subtotals */
estimated_subtotal_sans_list:[ans10,ans11,ans12,ans13];
estimated_subtotal_tans_list:[estimated_subtotal_1,estimated_subtotal_2,estimated_subtotal_3,estimated_subtotal_4];
estimated_subtotal_cons_list:[ans6*count_1,ans7*count_2,ans8*count_3,ans9*count_4];
err_midpoints_x_cum_freq:[ans1*ans6,ans2*ans7,ans3*ans8,ans4*ans9];

/* This only tests the estimated mean */
cons_ans_15:ans14/ans5;
error_div_by_intervals:total_weight/4;
cons_div_by_intervals:ans14/4;
